-- 0355 FORWARD ROLLBACK, A DRAFT (LOCAL SCENE). Generated by scripts/ops/harness/captain-skills/gen-checks.mjs from the migration's own hunks.
-- WHAT IT DOES: puts public.crew_terms back to its text before 0355 (the four hunks reversed, each found once), so no step is read by any rule,
-- and closes the door (cmd.captain_skill_up answers E_NOT_IN_USE), so nobody pays for a step that does nothing. The table, the rows, the knobs, the
-- ceilings, the read and the registry rows stay: a step bought is kept and reads as nothing until the term is cut in again.
-- TO DEPLOY IT (owner only): copy this file to supabase/migrations/<prod head + 1>_captain_skills_are_put_back.sql, DELETE THE FIRST LINE (the guard),
-- replace 03NN by its number, open a PR and deploy it with ~/bin/bv-deploy.sh. Tested on the local world after 0355 by the builder (dev-log).
do $m$
declare
  c_terms constant text := 'public.crew_terms(uuid,timestamp with time zone)';
  v_def   text;
  v_acl   text;
  v_meta  text;
  h       record;
  v_n     int;
begin
  perform set_config('statement_timeout', '45s', true);
  perform set_config('lock_timeout', '5s', true);
  if to_regclass('public.captain_trait_rank') is null or to_regprocedure('cmd.captain_skill_up(text,text)') is null then
    raise exception '03NN refuses: 0355 is not in this world';
  end if;
  select coalesce(p.proacl::text, ''), p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') into v_acl, v_meta from pg_proc p where p.oid = c_terms::regprocedure;
  v_def := replace(pg_get_functiondef(c_terms::regprocedure), E'\r', '');
  for h in select * from (values
    (1,
$n$             j.job_pct * public.captain_level_mult(po.id, jt.focus)
             * case when tr.rank is null then 1 else public.captain_rank_mult(tr.rank) end   -- 0355 (R2): her job's step; no row reads no knob
$n$,
$o$             j.job_pct * public.captain_level_mult(po.id, jt.focus)
$o$),
    (2,
$n$        join public.trait_effects te on te.trait = j.job
        left join public.captain_trait_rank tr on tr.player_officer_id = po.id and tr.trait = j.job   -- 0355 (R2): a merchant's captain never has a row
$n$,
$o$        join public.trait_effects te on te.trait = j.job
$o$),
    (3,
$n$             * te.mult * public.captain_level_mult(po.id, t.focus)
             * case when tr.rank is null then 1 else public.captain_rank_mult(tr.rank) end   -- 0355 (R2): the skill's step; no row reads no knob
$n$,
$o$             * te.mult * public.captain_level_mult(po.id, t.focus)
$o$),
    (4,
$n$        join public.trait_effects te on te.trait = ca.trait
        left join public.captain_trait_rank tr on tr.player_officer_id = po.id and tr.trait = ca.trait   -- 0355 (R2): a merchant's captain never has a row
$n$,
$o$        join public.trait_effects te on te.trait = ca.trait
$o$)
  ) x(n, new, old) order by x.n desc loop
    v_n := (length(v_def) - length(replace(v_def, h.new, ''))) / length(h.new);
    if v_n <> 1 then
      raise exception '03NN slice: hunk % of public.crew_terms occurs % time(s), expected exactly 1: the deployed body is not the one 0355 left', h.n, v_n;
    end if;
    v_def := replace(v_def, h.new, h.old);
  end loop;
  execute v_def;
  execute $f$
create or replace function cmd.captain_skill_up(p_code text, p_trait text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $body$
-- 03NN: THE DOOR IS CLOSED (0355 rolled back): public.crew_terms reads no step, so none is sold. Steps already bought are kept.
begin
  if public.current_player_id() is null then
    return jsonb_build_object('ok', false, 'error_code', 'E_NOT_SIGNED_IN', 'error_message', 'Nobody is signed in.', 'fixes', jsonb_build_array('(sign in)'));
  end if;
  return jsonb_build_object('ok', false, 'error_code', 'E_NOT_IN_USE', 'error_message', 'Captain skills are not in use.', 'fixes', '[]'::jsonb);
end
$body$
  $f$;
  if pg_get_functiondef(c_terms::regprocedure) ~ 'captain_trait_rank|captain_rank_mult'
     or (select coalesce(p.proacl::text, '') from pg_proc p where p.oid = c_terms::regprocedure) <> v_acl
     or (select p.provolatile::text || p.prosecdef::text || coalesce(p.proconfig::text, '') from pg_proc p where p.oid = c_terms::regprocedure) <> v_meta
     or not has_function_privilege('authenticated', 'cmd.captain_skill_up(text,text)', 'execute')
     or has_function_privilege('anon', 'cmd.captain_skill_up(text,text)', 'execute')
     or (cmd.captain_skill_up('X', 'Y') ->> 'error_code') is distinct from 'E_NOT_SIGNED_IN' then
    raise exception '03NN self-assert FAIL: public.crew_terms still reads a step, its ACL or volatility moved, or the door is not closed as it was granted';
  end if;
  raise notice '03NN self-assert ok: CAPTAIN SKILLS ARE PUT BACK. public.crew_terms is its text before 0355 (4 hunks reversed, each once; ACL, volatility, definer and config unmoved) and reads no step; cmd.captain_skill_up answers E_NOT_IN_USE; the table, its rows, the knobs, the ceilings and the read stay.';
end
$m$;
